<?php require_once __DIR__.'/../includes/functions.php';$rows=db()->query('SELECT * FROM public_announcements WHERE status="Published" AND publish_date<=CURDATE() AND (expiry_date IS NULL OR expiry_date>=CURDATE()) ORDER BY publish_date DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Announcements | CHMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=BASE_URL?>/assets/css/public.css" rel="stylesheet"></head><body><?php include __DIR__.'/../includes/public_nav.php';?><main class="container py-5"><h1>Announcements</h1><?php if(!$rows):?><div class="public-card mt-4">No public announcements are currently published.</div><?php else:foreach($rows as $a):?><article class="public-card my-3"><small><?=e($a['publish_date'])?></small><h3><?=e($a['title'])?></h3><p><?=nl2br(e($a['content']))?></p></article><?php endforeach;endif;?></main></body></html>
